export const MAP_W = 1000;
export const MAP_H = 449.5;
const LON0 = 100.0;
const MINX = -42.603161;
const MINY = -81.854175;
const SCALE = 11.057131;
const KX = 0.529919;

export const project = (lon: number, lat: number): [number, number] => {
  const l = lon < 0 ? lon + 360 : lon;
  return [((l - LON0) * KX - MINX) * SCALE, (-lat - MINY) * SCALE];
};

export const unproject = (x: number, y: number): [number, number] => {
  const lat = -(y / SCALE + MINY);
  const lon = (x / SCALE + MINX) / KX + LON0;
  return [lon > 180 ? lon - 360 : lon, lat];
};

